"""Generate exact cut absorption plus same-checker compiler/native construction."""
import hashlib,json,os,re
from pathlib import Path
S=Path(__file__).resolve().parent;R=S.parents[1];O=R/'outputs/mac-poseidon-width3-08';P=S/'project/ShielddSecurity'
sha=lambda b:hashlib.sha256(b).hexdigest()
b=(O/'rounds01.json').read_bytes();assert sha(b)=='fde97d467a132f7a53d037515cd35fbdcdf24c7f393b3195d1aa38885ca7f575';d=json.loads(b)
assert d['parameters']==json.loads((R/'work/runtime-snapshot/crates/crypto/primitives/params/poseidon381.json').read_text())
ports={n['source_node']:n['expression']['terms'] for n in d['selected_rounds'][0]['external_ports']};assert set(ports)=={16577,21951}
files=[]
def save(name,text):
 payload=text.encode();p=P/(name+'.lean')
 if p.exists() and p.read_bytes()!=payload:
  h=O/'source-history';h.mkdir(exist_ok=True);(h/(name+'-'+sha(p.read_bytes())+'.lean')).write_bytes(p.read_bytes())
 tmp=p.with_suffix('.tmp');tmp.write_bytes(payload);os.replace(tmp,p);files.append(dict(module=name,sha256=sha(payload),bytes=len(payload)))
lines=['-- GENERATED by generate_absorption.py; edit maintained sources.','import ShielddSecurity.TransferPoseidonWidth3R0008Proof01','namespace ShielddSecurity.TransferPoseidonWidth3Absorb08','open Compiler Poseidon','open TransferPoseidonWidth3R0008']
for i,source in enumerate([16577,21951]):lines.append(f'def input{i} : Linear := ['+', '.join(f'({c},{v})' for c,v in ports[source])+']')
lines += ['def inputs (input : Fin 2) : Linear := if input.val=0 then input0 else input1','def inputList (candidate : Fin 2 → Linear) : List Linear := [candidate 0,candidate 1]','def cutTerms2 (candidate : Fin 2 → Linear) (input : Nat) : Linear := if bound : input<2 then candidate ⟨input,bound⟩ else []','def absorptionCheck (domain arity : Nat) (candidateInputs : Fin 2 → Linear) (candidateBefore : State Linear 3) : Bool :=','  (List.finRange 3).all (fun column => decide (canonical p (candidateBefore column)=canonical p (absorbLinear (initialLinear domain arity) (inputList candidateInputs) column)))','def productionCheck (rows : Array Row) (candidate : Parameters Int 3) (candidateBefore candidateAfter : State Linear 3)','    (hints : Fin 3 → PoseidonIndexedFolded02.FifthHint) (mapping : Array Nat) (domain arity : Nat) (candidateInputs : Fin 2 → Linear) : Bool :=','  TransferPoseidonWidth3R0008.productionCheck rows candidate candidateBefore candidateAfter hints mapping &&','  absorptionCheck domain arity candidateInputs candidateBefore &&','  CompilerPriorFrame01.checkSupport 2 (cutTerms2 candidateInputs) steps','end ShielddSecurity.TransferPoseidonWidth3Absorb08']
save('TransferPoseidonWidth3Absorb08Data01','\n'.join(lines)+'\n')
template=(S/'absorption-proof-template.lean.txt').read_text();names=re.findall(r'^theorem (\w+)',template,re.M)
for name in names:template+=f'\nset_option pp.all true in\n#check @ShielddSecurity.TransferPoseidonWidth3Absorb08Proof01.{name}\n#print axioms ShielddSecurity.TransferPoseidonWidth3Absorb08Proof01.{name}\n'
save('TransferPoseidonWidth3Absorb08Proof01',template)
i=1
while (O/f'absorption-generation{i:02d}.json').exists():i+=1
(O/f'absorption-generation{i:02d}.json').write_text(json.dumps(dict(generator_sha256=sha(Path(__file__).read_bytes()),template_sha256=sha((S/'absorption-proof-template.lean.txt').read_bytes()),descriptor_sha256=sha(b),sources=files,scope='two captured cut LCs; upstream closure OPEN'),indent=2)+'\n')
print(json.dumps(files))
